css:
.radio-input {
  width: 210px;
  height: 210px;
  background-color: black;
  border-radius: 30px;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  padding: 6px;
  gap: 4px;
  position: relative;
  z-index: -1;
}

.radio-input input {
  display: none;
}

.radio-input .label {
  background: linear-gradient(to bottom, #333333, rgb(36, 35, 35));
  border-radius: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  border-top: 1px solid #4e4d4d;
  cursor: pointer;
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 200ms;
  box-shadow: 0px 0px 5px 1px rgba(0, 0, 0, 0.2);
}

.label:has(input[type="radio"]:checked) {
  box-shadow: 0px 17px 5px 1px rgba(0, 0, 0, 0);
  background: linear-gradient(to bottom, #1d1d1d, #1d1d1d);
  border-top: none;
}

.label::before {
  content: "";
  width: 100%;
  height: 100%;
  scale: 1.02;
  border-radius: 25px;
  background: linear-gradient(
      to bottom,
      transparent 10%,
      transparent,
      transparent 90%
    ),
    linear-gradient(to left, transparent 10%, transparent, transparent 90%);
  transition-property: all;
  transition-timing-function: cubic-bezier(0.4, 0, 0.2, 1);
  transition-duration: 200ms;
  z-index: -1;
}

.label.spring:has(input[type="radio"]:checked)::before {
  background: linear-gradient(
      to bottom,
      transparent 10%,
      #d88fa3,
      transparent 90%
    ),
    linear-gradient(to left, transparent 10%, #d88fa3, transparent 90%);
}

.label.summer:has(input[type="radio"]:checked)::before {
  background: linear-gradient(
      to bottom,
      transparent 10%,
      #e6b800,
      transparent 90%
    ),
    linear-gradient(to left, transparent 10%, #e6b800, transparent 90%);
}

.label.autumn:has(input[type="radio"]:checked)::before {
  background: linear-gradient(
      to bottom,
      transparent 10%,
      #c76b00,
      transparent 90%
    ),
    linear-gradient(to left, transparent 10%, #c76b00, transparent 90%);
}

.label.winter:has(input[type="radio"]:checked)::before {
  background: linear-gradient(
      to bottom,
      transparent 10%,
      #7fa8c4,
      transparent 90%
    ),
    linear-gradient(to left, transparent 10%, #7fa8c4, transparent 90%);
}

.label .text {
  color: black;
  font-size: 13px;
  line-height: 12px;
  padding: 0px;
  font-weight: 700;
  text-transform: uppercase;
  transition: all 0.1s linear;
  text-shadow:
    -1px -1px 1px rgb(224, 224, 224, 0.1),
    0px 2px 3px rgb(0, 0, 0, 0.3);
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}

.label input[type="radio"]:checked + .spring {
  color: #ffc0cb;
  text-shadow: 0px 0px 12px #d88fa3;
}

.label input[type="radio"]:checked + .summer {
  color: #ffd700;
  text-shadow: 0px 0px 12px #e6b800;
}

.label input[type="radio"]:checked + .autumn {
  color: #ff8c00;
  text-shadow: 0px 0px 12px #c76b00;
}

.label input[type="radio"]:checked + .winter {
  color: #add8e6;
  text-shadow: 0px 0px 12px #7fa8c4;
}

.center {
  width: 12px;
  height: 12px;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%) rotate(45deg);
  background-color: #333333;
  border-radius: 2px;
  border: 1px solid #4e4d4d;
  transition: all 0.12s linear;
}

.radio-input:has(.spring input:checked) .center {
  border-left: 1px solid #ffc0cbb2;
  box-shadow: inset 11px 0px 10px -12px #ffc0cbdc;
}

.radio-input:has(.summer input:checked) .center {
  border-top: 1px solid#ffd900d8;
  box-shadow: inset 0px 11px 10px -12px #ffd700;
}

.radio-input:has(.autumn input:checked) .center {
  border-bottom: 1px solid #ff8c00b2;
  box-shadow: inset 0px -11px 10px -12px #ff8c00;
}

.radio-input:has(.winter input:checked) .center {
  border-right: 1px solid #add8e694;
  box-shadow: inset -11px 0px 10px -12px #add8e6;
}
